#include<iostream>
#include<vector>
#include<string>
#include <utility> 
#include <sstream>
#include<algorithm> 
#include<cmath>
#include<map>
using namespace std;
​
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
​
    int m,n,x,y;
    cin >> m >> n >> x >> y;
    vector<int> products;
    for (int i = 0; i < n; i++) {
        int e, r;
        cin >> e >> r;
        // 风险值高于x的不考虑
        if (r > x){
            continue;
        }
        products.push_back(e);
    }
​
    // 按照收益率从大到小排序
    sort(products.begin(), products.end(), greater<int>());
    int reamin = m;
    long result  = 0;
    // 贪心选取收益率高的产品
    for (int i = 0; i < products.size() && reamin > 0; i++) {
        int cost = min(y, reamin);
        result  += 1L * cost * products[i];
        reamin -= cost;
    }
    //四舍五入保留结果
    cout << (int)round(result / 100.0) << "\n";
​
    return 0;
}

