public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
​
        // 处理输入
        int m = sc.nextInt(); // 可用于投资的总金额（万元）
        int n = sc.nextInt(); // 产品数量
        int x = sc.nextInt(); // 最大风险等级
        int y = sc.nextInt(); // 单个产品最大投资金额
​
        List<Integer> products = new ArrayList<>();
​
        for (int i = 0; i < n; i++) {
            int e = sc.nextInt(); // 收益率（百分比）
            int r = sc.nextInt(); // 风险等级
            // 风险值高于x的不考虑
            if (r > x) continue;
            products.add(e);
        }
​
        // 按照收益率从大到小排序
        products.sort(Collections.reverseOrder());
​
        int remain = m;
        long result = 0;
​
        // 贪心选取收益率高的产品
        for (int i = 0; i < products.size() && remain > 0; i++) {
            int cost = Math.min(y, remain);
            result += 1L * cost * products.get(i);
            remain -= cost;
        }
​
        // 四舍五入保留结果
        System.out.println(Math.round(result / 100.0));
    }
}
