  // 处理输入
  const [m, n, x, y] = inputLines[0].split(" ").map(Number);
  const products = [];
​
  // 读取产品信息
  for (let i = 1; i <= n; i++) {
    const [e, r] = inputLines[i].split(" ").map(Number);
    // 风险值高于x的不考虑
    if (r > x) continue;
    products.push(e);
  }
​
​
  // 按照收益率从大到小排序
​
  products.sort((a, b) => b - a);
​
  let remain = m;
  let result = 0;
