package main
​
import (
    "fmt"
    "math"
    "sort"
)
​
func main() {
    var m, n, x, y int
    fmt.Scan(&m, &n, &x, &y)
​
    products := []int{}
​
    // 读取产品数据
    for i := 0; i < n; i++ {
        var e, r int
        fmt.Scan(&e, &r)
        // 风险值高于x的不考虑
        if r > x {
            continue
        }
        products = append(products, e)
    }
​
    // 按照收益率从大到小排序
    sort.Sort(sort.Reverse(sort.IntSlice(products)))
​
    remain := m
    var result int64 = 0
​
    // 贪心选取收益率高的产品
    for i := 0; i < len(products) && remain > 0; i++ {
        cost := y
        if remain < y {
            cost = remain
        }
        result += int64(cost * products[i])
        remain -= cost
    }
​
    // 四舍五入保留结果
    fmt.Println(int(math.Round(float64(result) / 100.0)))
}
